input.command:
cd /Users/gabe/Projects/agent-plugins
echo "=== Checking for mid-paragraph hard wraps in body prose (lines that don't end in punctuation/tag but next line is lowercase continuation) ==="
for f in plugins/canon/agents/canon-drafter.md plugins/canon/agents/canon-drift-checker.md \
         plugins/lambda/agents/lambda-implementer.md plugins/lambda/agents/lambda-reviewer.md \
         plugins/lambda/agents/lambda-exit-gate.md plugins/lambda/agents/lambda-recon.md \
         plugins/vector/agents/vector-planner.md plugins/delta/agents/delta-changeset-analyzer.md \
         plugins/canon/skills/canon/SKILL.md plugins/lambda/skills/lambda/SKILL.md \
         plugins/vector/skills/vector/SKILL.md plugins/delta/skills/delta/SKILL.md \
         shared/constitution.md; do
  # look for lines within backstory/goal/judgment/output blocks (excluding code fences and tables) that are suspiciously short and followed by lowercase
  awk '
    /^```/{incode=!incode}
    incode{next}
    /^\|/{next}
    /^-/{next}
    /^[0-9]+\./{next}
    /^$/{next}
    {
      if (prevlen > 0 && prevlen < 100 && $0 ~ /^[a-z]/ && prev !~ /[.:!?`)—-]$/ ) {
        print FILENAME":"NR-1": possible wrap -> \""prev"\" / \""$0"\""
      }
    }
    {prev=$0; prevlen=length($0)}
  ' "$f"
done
echo "(done — nothing printed above means clean)"

cd /Users/gabe/Projects/agent-plugins
git diff -- plugins/canon/agents/canon-drafter.md plugins/canon/agents/canon-drift-checker.md \
  plugins/lambda/agents/lambda-implementer.md plugins/lambda/agents/lambda-reviewer.md \
  plugins/lambda/agents/lambda-exit-gate.md plugins/lambda/agents/lambda-recon.md \
  plugins/vector/agents/vector-planner.md plugins/delta/agents/delta-changeset-analyzer.md \
  plugins/canon/skills/canon/SKILL.md plugins/lambda/skills/lambda/SKILL.md \
  plugins/vector/skills/vector/SKILL.md plugins/delta/skills/delta/SKILL.md \
  shared/constitution.md shared/schemas/changeset@1.json shared/schemas/plan@1.json \
  plugins/canon/README.md plugins/lambda/README.md plugins/vector/README.md plugins/delta/README.md \
  plugins/canon/CHANGELOG.md plugins/lambda/CHANGELOG.md plugins/vector/CHANGELOG.md plugins/delta/CHANGELOG.md \
  2>&1 | awk '
    /^\+\+\+/{next}
    /^\+```/{next}
    /^\+\|/{next}
    /^\+[0-9]+\./{next}
    /^\+-/{next}
    /^\+$/{prev=""; next}
    /^\+/{
      line=substr($0,2)
      if (prev != "" && prev !~ /[.:!?`)—">-]$/ && line ~ /^[a-z]/) {
        print "SUSPECT: \""prev"\"  -->  \""line"\""
      }
      prev=line
      next
    }
    {prev=""}
  '

cd /Users/gabe/Projects/agent-plugins
for f in plugins/canon/agents/canon-drafter.md plugins/canon/agents/canon-drift-checker.md \
         plugins/lambda/agents/lambda-exit-gate.md plugins/lambda/agents/lambda-implementer.md \
         plugins/lambda/agents/lambda-recon.md plugins/lambda/agents/lambda-reviewer.md \
         plugins/vector/agents/vector-planner.md plugins/delta/agents/delta-changeset-analyzer.md \
         plugins/canon/skills/canon/SKILL.md plugins/lambda/skills/lambda/SKILL.md \
         plugins/vector/skills/vector/SKILL.md plugins/delta/skills/delta/SKILL.md \
         shared/constitution.md; do
  awk -v fname="$f" '
    /^```/{incode=!incode}
    incode{next}
    /^\|/{next}
    /^-/{next}
    /^[0-9]+\./{next}
    /^$/{prev=""; next}
    /^</{prev=""; next}
    {
      if (prev != "" && length(prev) < 100 && $0 ~ /^[a-z]/ && prev !~ /[.:!?`)—">-]$/) {
        print fname":"NR-1": \""prev"\" -> \""$0"\""
      }
      prev=$0
    }
  ' "$f"
done

cd /Users/gabe/Projects/agent-plugins
for f in plugins/canon/agents/canon-drafter.md plugins/canon/skills/canon/SKILL.md; do
  echo "=== $f ==="
  awk -v fname="$f" '
    /^```/{incode=!incode}
    incode{next}
    /^\|/{next}
    /^-/{next}
    /^[0-9]+\./{next}
    /^$/{prev=""; next}
    /^</{prev=""; next}
    /^name:|^role:|^model:|^effort:|^description:/{prev=""; next}
    {
      if (prev != "" && length(prev) < 100 && $0 ~ /^[a-z]/ && prev !~ /[.:!?`)—">-]$/) {
        print NR-1": \""prev"\" -> \""$0"\""
      }
      prev=$0
    }
  ' "$f"
done
echo "(nothing printed under a header = clean)"
jq . /Users/gabe/Projects/agent-plugins/marketplace.json > /dev/null && jq . /Users/gabe/Projects/agent-plugins/plugins/*/plugin.json > /dev/null && jq . /Users/gabe/Projects/agent-plugins/shared/schemas/*.json > /dev/null && echo "all JSON still valid"

